    "fragment ZC_UserStatisticTotals on RecordStatisticsConnection {\n  totalCount\n  aggregates {\n    sum {\n      distance\n    }\n  }\n}\n\nfragment ZC_UserV6StatisticAggregates on RecordStatisticAggregates {\n  sum {\n    distance\n    distanceInAir\n    distanceOn1Wheel\n    distanceOn2Wheels\n    distanceOn3Wheels\n    distanceOn4Wheels\n    distanceOnGrass\n    distanceOnGround\n    distanceOnIce\n    distanceOnMetal\n    distanceOnSand\n    distanceOnSnow\n    distanceOnSoap\n    distanceOnTarmac\n    distanceRagdoll\n    time\n    timeInAir\n    timeOnGrass\n    timeOnGround\n    timeOnIce\n    timeOnMetal\n    timeOnSand\n    timeOnSnow\n    timeOnSoap\n    timeOnTarmac\n    timeRagdoll\n    turnLeftCount\n    turnRightCount\n    armsUpCount\n    brakeCount\n    hornCount\n  }\n  average {\n    averageGforce\n    averageSpeed\n  }\n  max {\n    maxGforce\n    maxSpeed\n  }\n}\n\nquery ZC_UserStatistics($userId: Int!, $minimumModVersion: String!, $daySince: Datetime!, $monthSince: Datetime!, $yearSince: Datetime!) {\n  allStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}}}\n  ) {\n    ...ZC_UserStatisticTotals\n  }\n  dayStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, dateCreated: {greaterThanOrEqualTo: $daySince}}}\n  ) {\n    ...ZC_UserStatisticTotals\n  }\n  monthStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, dateCreated: {greaterThanOrEqualTo: $monthSince}}}\n  ) {\n    ...ZC_UserStatisticTotals\n  }\n  yearStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, dateCreated: {greaterThanOrEqualTo: $yearSince}}}\n  ) {\n    ...ZC_UserStatisticTotals\n  }\n  v6Statistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, modVersion: {greaterThanOrEqualTo: $minimumModVersion}}}\n  ) {\n    totalCount\n    aggregates {\n      ...ZC_UserV6StatisticAggregates\n    }\n  }\n  v6DayStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, dateCreated: {greaterThanOrEqualTo: $daySince}, modVersion: {greaterThanOrEqualTo: $minimumModVersion}}}\n  ) {\n    totalCount\n    aggregates {\n      ...ZC_UserV6StatisticAggregates\n    }\n  }\n  v6MonthStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, dateCreated: {greaterThanOrEqualTo: $monthSince}, modVersion: {greaterThanOrEqualTo: $minimumModVersion}}}\n  ) {\n    totalCount\n    aggregates {\n      ...ZC_UserV6StatisticAggregates\n    }\n  }\n  v6YearStatistics: recordStatistics(\n    first: 0\n    filter: {record: {userId: {equalTo: $userId}, dateCreated: {greaterThanOrEqualTo: $yearSince}, modVersion: {greaterThanOrEqualTo: $minimumModVersion}}}\n  ) {\n    totalCount\n    aggregates {\n      ...ZC_UserV6StatisticAggregates\n    }\n  }\n}": typeof types.Zc_UserStatisticTotalsFragmentDoc,
